def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    if n < 10:
        if opp[-1] == 'D':
            return 'D'
        return 'C'
    last_opp = opp[-1]
    last_me = me[-1]
    opp_def = sum(1 for a in opp[-10:] if a == 'D')
    me_def = sum(1 for a in me[-10:] if a == 'D')
    if opp_def >= 8:
        return 'D'
    if n >= 20:
        recent_opp_def = sum(1 for a in opp[-5:] if a == 'D')
        earlier_opp_def = sum(1 for a in opp[-20:-5] if a == 'D')
        if recent_opp_def >= 3 and earlier_opp_def <= 2:
            return 'D'
    if last_opp == 'D' and last_me == 'C':
        if n >= 3 and opp[-2] == 'C' and opp[-3] == 'C':
            return 'D'
        if rng.random() < 0.8:
            return 'D'
        return 'C'
    if last_opp == 'D' and last_me == 'D':
        if n >= 4 and opp[-3:-1] == ['C', 'C']:
            return 'C'
        return 'D'
    if last_opp == 'C':
        if me_def >= 6:
            if rng.random() < 0.3:
                return 'D'
        if opp_def >= 5:
            if rng.random() < 0.25:
                return 'D'
        return 'C'
    return 'C'
